def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None:
        v = s.get('basic_structure_statistics', {}).get('volume_per_atom_A3')
    if v is not None and math.isfinite(v) and v > 0.0:
        return float(math.log(v))
    return 0.0

def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None:
        v = s.get('basic_structure_statistics', {}).get('volume_per_atom_A3')
    if v is None or not math.isfinite(v) or v <= 0.0:
        return 0.0
    props = s.get('element_properties', {})
    total = 0.0
    weight = 0.0
    for e, x in s.get('composition', {}).items():
        r = props.get(e, {}).get('covalent_radius_A')
        if x is not None and x > 0.0 and r is not None and math.isfinite(r) and r > 0.0:
            total += x * r * r * r
            weight += x
    if weight > 0.0:
        return float(4.0 * math.pi * total / (3.0 * weight * v))
    return 0.0

def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None:
        v = s.get('basic_structure_statistics', {}).get('volume_per_atom_A3')
    if v is None or not math.isfinite(v) or v <= 0.0:
        return 0.0
    props = s.get('element_properties', {})
    total = 0.0
    weight = 0.0
    for e, x in s.get('composition', {}).items():
        z = props.get(e, {}).get('valence_electrons')
        if x is not None and x > 0.0 and z is not None and math.isfinite(z) and z >= 0.0:
            total += x * z
            weight += x
    if weight > 0.0:
        return float(total / (weight * v))
    return 0.0

def feature(s):
    sites = s.get('sites', [])
    if len(sites) == 0:
        return 0.0
    props = s.get('element_properties', {})
    radii = [props.get(t.get('element', ''), {}).get('covalent_radius_A') for t in sites]
    occ = [max(0.0, float(t.get('occupancy', 1.0) or 0.0)) for t in sites]
    result = math.inf
    for b in s.get('neighbors', []):
        i = b['i']
        j = b['j']
        d = b['distance_A']
        ri = radii[i]
        rj = radii[j]
        if d > 1e-8 and occ[i] > 0.0 and occ[j] > 0.0 and ri is not None and rj is not None:
            if math.isfinite(ri) and math.isfinite(rj) and ri > 0.0 and rj > 0.0:
                result = min(result, d / (ri + rj))
    if math.isfinite(result):
        return float(result)
    return 0.0

def feature(s):
    props = s.get('element_properties', {})
    terms = []
    for e, x in s.get('composition', {}).items():
        p = props.get(e, {})
        ionization = p.get('first_ionization_energy_eV')
        affinity = p.get('electron_affinity_eV')
        if x is not None and math.isfinite(x) and x > 0.0 and ionization is not None and affinity is not None:
            if math.isfinite(ionization) and math.isfinite(affinity):
                chi = 0.5 * (ionization + affinity)
                hardness = max(0.5, ionization - affinity)
                terms = terms + [(x, chi, hardness)]
    weight = sum(t[0] for t in terms)
    denominator = sum(t[0] / t[2] for t in terms)
    if weight > 0.0 and denominator > 0.0:
        chemical_potential = sum(t[0] * t[1] / t[2] for t in terms) / denominator
        variance = sum(t[0] * ((chemical_potential - t[1]) / t[2]) ** 2 for t in terms) / weight
        return float(math.sqrt(max(0.0, variance)))
    return 0.0

